# typed: false
# frozen_string_literal: true

# Homebrew formula for the Engra CLI. Generated by packaging/release.py in the
# release workflow; do not hand-edit. Release assets live in
# arenberg-engineering/engra-releases.
class Engra < Formula
  desc "AI coding agent and developer assistant for the terminal"
  homepage "https://engra.io"
  # Proprietary software of Arenberg AG, all rights reserved (LICENSE.txt).
  license :cannot_represent

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.35/engra-0.4.35-macos-arm64.tar.gz"
      sha256 "301b6f45464b419a3e9c0023aab37adb4003cf49552b776528c83f0fb7d4fc8b"
    end
    on_intel do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.35/engra-0.4.35-macos-x64.tar.gz"
      sha256 "4a20f4ffc7f0a1dc55c53add493eb46af00cf8f2f127a4d5fcd9f1eb8eda70a2"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.35/engra-0.4.35-linux-arm64.tar.gz"
      sha256 "5769e73f43784ebe42e1e6774a9c6de61d210b8e1a19680651227c2159caa589"
    end
    on_intel do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.35/engra-0.4.35-linux-x64.tar.gz"
      sha256 "2db064ef16ed11df9b09c214b1ab504da0723b7a4d2b9d1a6c7ddf42839a07e8"
    end
  end

  def install
    libexec.install "engra", "_internal"
    bin.install_symlink libexec/"engra"
    prefix.install "LICENSE.txt", "TERMS.md", "THIRD_PARTY_NOTICES.txt"
  end

  def caveats
    <<~EOS
      Sign in with:
        engra login

      Terms of Use: engra legal --terms

      Before uninstalling, run `engra logout` to remove saved credentials from
      the OS keychain. Settings and link state stay in ~/.config/engra (and
      doctor records in ~/.engra); remove them to clear everything.
    EOS
  end

  test do
    assert_equal "engra #{version}", shell_output("#{bin}/engra --version").strip
    assert_match "doctor", shell_output("#{bin}/engra --help")
    assert_match "Arenberg AG", shell_output("#{bin}/engra legal")
  end
end
